//soniox.com","role":"Real-time speech-to-text — the ears on the Baguette Index calls","referral":null,"usedBy":["Le Baguette Index"],"category":"agents"},{"name":"Apify","url":"https://apify.com","role":"Actor marketplace for scraping & automation — this index's own pulse runs its X/LinkedIn sources on it","referralUrl":"https://www.apify.com?fpr=723ji2","referral":"Affiliate: 20% → 30% recurring, up to $2,500/customer","usedBy":["Autopilot Index (this site)"],"category":"agents"},{"name":"Vapi","url":"https://vapi.ai","role":"Voice agents by API — dial, listen, respond; the fast path to a 'Rachel' of your own","referral":null,"usedBy":["Solo builders"],"category":"agents"},{"name":"Browserbase","url":"https://browserbase.com","role":"Headless browsers for agents at scale — sessions, stealth & replays","referral":null,"usedBy":["Solo builders"],"category":"agents"},{"name":"Firecrawl","url":"https://firecrawl.dev","role":"Websites → LLM-ready data — the web-reading layer for agent pipelines","referral":"Affiliate link — referred users get 10% off their first purchase","referralUrl":"https://firecrawl.link/autopilot-index","usedBy":["Solo builders"],"category":"agents"},{"name":"n8n","url":"https://n8n.io","role":"Self-hostable workflow automation with agent nodes — the glue of one-person ops","referral":"Affiliate: 30% for 12 months (cloud)","referralUrl":"https://n8n.partnerlinks.io/v62otr8v5os3","usedBy":["Solo builders"],"category":"agents"},{"name":"Resend","url":"https://resend.com","role":"The transactional-email API this generation of builders reaches for","referral":null,"usedBy":["Solo builders"],"category":"distribution"},{"name":"Polar","url":"https://polar.sh","role":"Merchant of record for one-person software businesses — global sales tax handled, checkout in minutes","referral":null,"usedBy":["Solo builders"],"category":"payments"},{"name":"Langfuse","url":"https://langfuse.com","role":"Open-source agent/LLM observability — what did my agents actually