companies.sort((a,b)=>(order.indexOf(a.slug)<0?99:order.indexOf(a.slug))-(order.indexOf(b.slug)<0?99:order.indexOf(b.slug)));
const state={tab:'Companies',domain:'All',level:'All',section:'All',q:'',sort:'',dir:1};
const defs=[['L1','Assisted','People do the work; AI helps with individual tasks.'],['L2','Function','AI executes a bounded business function with human oversight.'],['L3','Operational','Agents coordinate recurring operations; people handle exceptions.'],['L4','Goal-level','People set goals; agents plan and execute across functions.'],['L5','Full autonomy','End-to-end business operation with minimal human intervention.']];
const app=document.querySelector('#app');
app.innerHTML=`<main class="container"><header class="masthead"><a class="brand" href="/"><img src="/registry/favicon.svg" alt="">Autopilot Index</a><span class="strap">People, tools & evidence.</span><span class="byline">Curated by Antonio Serrano</span><div class="mast-links"><button data-action="sponsor">Sponsor</button><a class="subscribe" href="https://autopilotindex.com/pulse" target="_blank" rel="noopener">Read the newsletter ↗</a></div></header><nav class="main-tabs" aria-label="Directory"><button data-tab="Companies" class="active">Companies</button><button data-tab="Builder stack">Builder stack</button><button data-tab="Pulse">Pulse</button><a href="workbench.html">Workflow concept ↗</a></nav><section class="intro"><h1>A field guide to the autonomous-business era.</h1><p><strong>Less headcount. More possibility.</strong> Agents, agent swarms and AI at work — the companies building it, the people behind them, and the evidence that matters.</p></section><div id="controls"></div><div class="search-row"><label class="search"><span>⌕</span><input id="search" aria-label="Search the registry" placeholder="Search companies, founders, tools…" autocomplete="off"><kbd>/</kbd></label><span class="count" id="count" aria-live="polite"></span><div class="display-controls"><label>Density <select id="density"><option value="compact">Compact</option><option value="comfortable">Comfortable</option></select></label><button class="clear" data-action="reset">Reset</button></div></div><div id="results"></div><div class="inline-pulse"><strong>The Autopilot Pulse</strong><span>Companies, tools and evidence from the autonomous-business frontier.</span><a href="https://autopilotindex.com/pulse" target="_blank" rel="noopener">Explore the newsletter ↗</a></div><footer class="foot">Research snapshot · Profile links added October 12, 2026. <button data-action="method">How to read this index</button><span> · </span><button data-action="sponsor">Sponsor the field guide</button></footer></main><dialog id="detail"><div class="dialog-head"><strong id="dialog-title"></strong><button data-action="close" aria-label="Close dialog">×</button></div><div class="dialog-body" id="dialog-body"></div></dialog>`;
function chips(key,values){return `<div class="filter-line"><span class="filter-label">${key==='section'?'Collection':key==='level'?'Autonomy':'Domain'}</span>${values.map(v=>`<button class="chip ${state[key]===v?'active':''}" data-filter="${key}" data-value="${E(v)}" aria-pressed="${state[key]===v}">${E(v)}</button>`).join('')}${key==='level'?'<button class="framework-button" data-action="framework">L1–L5 explained ↗</button>':''}</div>`}
function controls(){document.querySelector('#controls').innerHTML=state.tab==='Companies'?`<div class="filters">${chips('domain',['All',...new Set(companies.map(c=>c.domain))])}${chips('level',['All','L1','L2','L3','L4','L5','Not assessed'])}${chips('section',['All','Index','Watchlist','Enabler','Caution','Unclassified'])}</div>`:`<p class="tab-description">${state.tab==='Builder stack'?'The technology behind the companies: agents, models, infrastructure and workflow tools.':'Dispatches from the autonomous-business era. Read the full edition on Autopilot Index.'}</p>`;}
function face(f){let p=profiles[f.name],inner=p?`<img src="/registry/assets/people/${p[1]}.jpg" alt="${E(f.name)}" loading="lazy">`:`<span>${E(f.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span>`;return p?A('https://x.com/'+p[0],inner,'face'):`<span class="face initial" title="${E(f.name)} — social profile not linked">${inner}</span>`}
function people(c){return `<div class="people"><span class="faces">${c.founders.map(face).join('')}</span><span class="people-names">${c.founders.map(f=>profiles[f.name]?A('https://x.com/'+profiles[f.name][0],E(f.name)):E(f.name)).join(', ')}</span></div>`}
function level(c){let a=c.autopilot||{};return a.level?`<button class="level ${a.section==='watchlist'?'claim':''}" data-company="${c.slug}" title="${a.section==='watchlist'?'Claim / watchlist':'Editorial assessment'} — view evidence">${a.level}${a.section==='watchlist'?'*':''}</button>`:'<span class="unassessed" title="Business autonomy not assessed">—</span>'}
function team(c){let h=OBSERVATIONS[c.slug]?.headcount;if(!h||h.value===null)return h?.status==='disputed'?`<button class="team-link" data-company="${c.slug}">Disputed</button>`:'<span class="unassessed">—</span>';return `<button class="team-link" data-company="${c.slug}" title="${E(h.display)} · ${E(h.asOf||'Date unavailable')}">${E(h.value)}${h.precision==='lower_bound'?'+':''}${!h.asOf?'<span class="undated">†</span>':''}</button>`}
function logo(c){return ['semio','medvi'].includes(c.slug)?`<span class="face initial">${E(c.name[0])}</span>`:`<img src="/registry/assets/${logos[c.slug]||c.slug}.png" alt="" loading="lazy">`}
function evidence(c){let n=c.news?.find(n=>n.url);let o=OBSERVATIONS[c.slug];let source=o?.financial?.source||o?.headcount?.source;return n?A(n.url,E(n.headline),'source-link'):source?A(source.url,E(source.name),'source-link'):`<button class="source-link" data-company="${c.slug}">Research notes</button>`}
function stack(c){return (c.techStack||[]).slice(0,2).map(n=>{let t=CONTENT.stackTools.find(x=>x.name.toLowerCase()===n.toLowerCase());return A(t?.url,E(n));}).join(' · ')+((c.techStack||[]).length>2?` <button class="extra" data-company="${c.slug}">+${c.techStack.length-2}</button>`:'')}
function render(){let list=companies.filter(c=>(state.domain==='All'||c.domain===state.domain)&&(state.level==='All'||(state.level==='Not assessed'?!c.autopilot?.level:c.autopilot?.level===state.level))&&(state.section==='All'||(/disput|warning|investigation/i.test(c.autopilot?.flags||'')?'Needs review':c.autopilot?.section==='index'?'Assessed':c.autopilot?.level?'Claims':'Unassessed')===state.section)&&JSON.stringify(c).toLowerCase().includes(state.q.toLowerCase()));
if(state.sort)list.sort((a,b)=>{let val=c=>state.sort==='team'?OBSERVATIONS[c.slug]?.headcount?.value:state.sort==='level'?c.autopilot?.level:state.sort==='founders'?c.founders[0]?.name:c[state.sort];let x=val(a),y=val(b);if(x==null)return y==null?0:1;if(y==null)return -1;return (typeof x==='number'?x-y:String(x).localeCompare(String(y)))*state.dir;});
let html='';if(state.tab==='Companies'){let heads=[['name','Company'],['domain','Domain'],['level','Autonomy'],['focus','AI at work'],['','Team background'],['founders','Founders & builders'],['team','Team'],['','Technology stack'],['','Evidence / sources']];html=`<table class="registry-table"><colgroup>${heads.map(()=>'<col>').join('')}</colgroup><thead><tr>${heads.map(([k,t])=>`<th ${k?`aria-sort="${state.sort===k?(state.dir===1?'ascending':'descending'):'none'}"`:''}>${k?`<button data-sort="${k}">${t}</button>`:t}</th>`).join('')}</tr></thead><tbody>${list.map(c=>`<tr><td><div class="co">${logo(c)}${A(c.url,E(c.name))}<button class="detail" data-company="${c.slug}" aria-label="Research notes for ${E(c.name)}">＋</button></div></td><td><span class="domain-tag domain-${c.domain}">${c.domain}</span></td><td>${level(c)}</td><td class="focus" title="${E(c.focus)}">${E(c.focus)}</td><td class="background" title="${E(c.founders.map(f=>f.background).join(' · '))}">${E(c.founders.map(f=>f.background).join(' · '))}</td><td>${people(c)}</td><td>${team(c)}</td><td class="stack-links" title="${E(c.techStack?.join(', '))}">${stack(c)||'—'}</td><td>${evidence(c)}</td></tr>`).join('')||'<tr class="empty"><td colspan="9">No matching records. Try another filter or reset.</td></tr>'}</tbody></table><p class="table-note">L2 / L3 = editorial assessment · * = watchlist claim · — = not assessed or unavailable · † = team figure has no observation date. Team counts have different scopes; click for context. Click ＋ for full research.</p>`;document.querySelector('#count').textContent=`${list.length} of ${companies.length} records`;
}else if(state.tab==='Builder stack'){let ts=CONTENT.stackTools.filter(t=>JSON.stringify(t).toLowerCase().includes(state.q.toLowerCase()));html=`<table class="registry-table tools-table"><thead><tr><th>Tool</th><th>Category</th><th>What it does</th><th>Used by</th><th>Website</th></tr></thead><tbody>${ts.map(t=>`<tr><td>${A(t.url,E(t.name))}</td><td><span class="domain-tag">${E(t.category)}</span></td><td title="${E(t.role)}">${E(t.role)}</td><td>${E(t.usedBy?.join(', ')||'—')}</td><td>${A(t.url,'Visit ↗')}</td></tr>`).join('')}</tbody></table>`;document.querySelector('#count').textContent=`${ts.length} tools`;
}else{let es=CONTENT.editions.filter(e=>e.title.toLowerCase().includes(state.q.toLowerCase()));html=`<div class="pulse-list">${es.map(e=>`<article class="edition"><span>№ ${e.number} · ${E(e.date)}</span><h2>${A('https://autopilotindex.com/pulse/'+e.slug,E(e.title))}</h2><a href="https://autopilotindex.com/pulse/${E(e.slug)}" target="_blank" rel="noopener">Read edition ↗</a></article>`).join('')}</div>`;document.querySelector('#count').textContent=`${es.length} editions`;}
document.querySelector('#results').innerHTML=html;}
function modal(title,body){document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-body').innerHTML=body;document.querySelector('#detail').showModal()}
function company(slug){let c=companies.find(c=>c.slug===slug),o=OBSERVATIONS[slug]||{};modal(c.name,`<p>${E(c.description)}</p><dl class="panel-facts"><dt>Business autonomy</dt><dd>${E(c.autopilot?.level||'Not assessed')}${c.autopilot?.level?' · '+(c.autopilot.section==='watchlist'?'watchlist claim':'editorial assessment'):''}</dd><dt>Collection</dt><dd>${E(c.autopilot?.section||'Unclassified')}</dd><dt>AI at work</dt><dd>${E(c.focus)}</dd></dl>${c.autopilot?.flags?`<p class="note">${E(c.autopilot.flags)}</p>`:''}<h3>Founders & builders</h3>${c.founders.map(f=>`<div class="detail-person">${face(f)}<div><strong>${profiles[f.name]?A('https://x.com/'+profiles[f.name][0],E(f.name)+' ↗'):E(f.name)}</strong><p>${E(f.background)}</p></div></div>`).join('')}<h3>Team & financial observations</h3>${['headcount','financial','contractors'].map(k=>o[k]?`<div class="source-item"><strong>${E(o[k].display)}</strong><p>${E(o[k].asOf||'Observation date unavailable')} · ${E(o[k].status)}${o[k].population?' · '+E(o[k].population.replaceAll('_',' ')):''}</p><p>${E(o[k].notes||'')}</p>${A(o[k].source?.url,E(o[k].source?.name||'Source')+' ↗')}</div>`:'').join('')||'<p>No sourced observations in this snapshot.</p>'}<h3>Technology stack</h3><p>${stack(c)||'Not documented'}</p><h3>Sources & updates</h3>${(c.news||[]).map(n=>`<div class="source-item"><small>${E(n.date)}</small><p>${A(n.url,E(n.headline)+' ↗')}</p></div>`).join('')}<div class="detail-actions">${A(c.url,'Company website ↗','outline-link')}${A('https://autopilotindex.com/companies/'+c.slug,'Company profile ↗','outline-link')}</div>`)}
listen(app,'click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.filter){state[b.dataset.filter]=b.dataset.value;controls();render()}else if(b.dataset.sort){state.dir=state.sort===b.dataset.sort?-state.dir:1;state.sort=b.dataset.sort;render()}else if(b.dataset.company)company(b.dataset.company);else if(b.dataset.tab){state.tab=b.dataset.tab;state.q='';document.querySelector('#search').value='';document.querySelectorAll('[data-tab]').forEach(n=>n.classList.toggle('active',n===b));controls();render()}else if(b.dataset.action==='close')document.querySelector('#detail').close();else if(b.dataset.action==='reset'){Object.assign(state,{domain:'All',level:'All',section:'All',q:'',sort:'',dir:1});document.querySelector('#search').value='';controls();render()}else if(b.dataset.action==='framework'||b.dataset.action==='method'){modal('Business autonomy: L1–L5',`<p>A proposed editorial framework for how a business operates. Selling an AI product does not establish that the company itself is autonomous.</p><table class="framework">${defs.map(d=>`<tr><th>${d[0]}</th><td><strong>${d[1]}</strong><p>${d[2]}</p></td></tr>`).join('')}</table><p class="note">Levels are research judgments, not certifications. An asterisk marks a claim under observation. L4 and L5 are not established outcomes in this snapshot. Source strength, human oversight and date matter more than the level alone.</p><p>Company records come from the existing Autopilot Index research snapshot. Portraits link to matching public X profiles. Missing profiles use initials. Headcount and financial observations retain their original source and scope.</p>`)}else if(b.dataset.action==='sponsor')modal('Sponsor the field guide',`<p>Reach readers exploring autonomous companies, agent workflows and the builder stack.</p><h3>Proposed sponsorship</h3><p>A clearly labeled placement alongside the registry, paired with a sponsored mention in an upcoming Pulse edition.</p><p>Audience, availability and pricing should be confirmed before booking. This preview does not accept payments.</p>${A('https://autopilotindex.com/pulse','Explore the publication ↗','outline-link')}`)});
document.querySelector('#search').addEventListener('input',e=>{state.q=e.target.value;render()});document.querySelector('#density').addEventListener('change',e=>document.body.classList.toggle('comfortable',e.target.value==='comfortable'));listen(document,'keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!document.querySelector('#detail').open){e.preventDefault();document.querySelector('#search').focus()}});controls();render();

