const toolsV3=CONTENT.stackTools.map((t,i)=>({...t,id:i,layer:layerOverrides[t.name]||layers.find(l=>l.slice(1).includes(t.category))?.[0]||'Other',type:toolTypes[t.name]||({'intelligence':'Model / inference','agents':'Agent infrastructure','rails':'Business infrastructure','payments':'Agent payments','distribution':'Distribution API','ops':'Evaluation','sandboxes':'Compute','code-deploy':'Cloud platform','data':'Data platform'}[t.category]),promotion:{status:'unverified',label:t.referral,code:null,affiliateUrl:null,expiresAt:null,checkedAt:null}}));
Object.assign(state,{layer:'All',toolCompany:'All',toolView:'Map + table',pulse:'Signals',signalKind:'All',flowFunction:'All',signalSort:'Impact'});
