face=function(f){let old=profiles[f.name],p=PORTRAITS[f.name],src=p?.image||(old?'/registry/assets/people/'+old[1]+'.jpg':null),url=personUrl(f),initials=E(f.name.split(' ').map(x=>x[0]).slice(0,2).join('')),platform=url&&/(?:x|twitter)\.com\//.test(url)?'X':url?.includes('linkedin.com')?'LinkedIn':'profile';let inner=`<span class="avatar-fallback" aria-hidden="true">${initials}</span>${src?`<img src="${E(src)}" alt="${E(f.name)}" loading="lazy" width="20" height="20">`:''}`;return url?`<a href="${E(url)}" target="_blank" rel="noopener noreferrer" class="face${src?'':' initial'}" title="${E(f.name)} · ${platform}" aria-label="${E(f.name)} on ${platform}">${inner}</a>`:`<span class="face initial" title="${E(f.name)} · profile not linked">${inner}</span>`};
listen(app,'error',e=>{if(e.target.matches?.('.face img')){e.target.hidden=true;e.target.parentElement.classList.add('initial')}},true);
