function fundamentalsCard(c){let d=FUNDAMENTALS[c.slug],o=OBSERVATIONS[c.slug]||{};if(d?.status!=='matched')return `<section class="fundamentals"><h3>Fundamentals</h3><p>Company fundamentals below retain their original sources.</p></section>`;return `<section class="fundamentals"><div class="fundamentals-heading"><h3>Fundamentals</h3>${A(d.url,'Dealroom ↗')}</div><div class="metric-grid"><div><small>TOTAL FUNDING</small><strong>${amount(d.funding?.total)}</strong><span>${d.funding?.rounds_count??'—'} recorded rounds</span></div><div><small>REVENUE · ${d.revenue?.year||'YEAR UNKNOWN'}</small><strong>${amount(d.revenue?.value)}</strong><span>Dealroom revenue field; not verified ARR</span></div><div><small>VALUATION · ${d.valuation?.year||'YEAR UNKNOWN'}</small><strong>${amount(d.valuation?.value)}</strong><span>Dealroom valuation; basis not provided</span></div><div><small>TEAM</small><strong>${d.employees??'—'}</strong><span>Dealroom · observation date unavailable</span></div></div>${d.employees!=null&&o.headcount?.value!=null&&d.employees!==o.headcount.value?`<p class="note">Source difference: Dealroom lists ${d.employees}; your research records ${E(o.headcount.display)} (${E(o.headcount.asOf||'undated')}). Different dates or counting methods may explain it. Neither has been overwritten.</p>`:''}<p class="fundamental-meta">Retrieved ${d.checkedAt.slice(0,10)} · USD · ${E(d.locations?.filter(l=>l.role==='hq').map(l=>[l.city?.name,l.country?.name].filter(Boolean).join(', ')).join(' / ')||'HQ not available')} · API retrieval is not independent confirmation.</p></section>`}
