function capitalMilestone(c){const d=FUNDAMENTALS[c.slug],f=c.funding||{};const stage=(f.lastRound||'').match(/pre-seed|seed|series\s+[a-f]/i)?.[0];
 if(c.slug==='base44')return {label:'Acquired · Wix',kind:'exit',detail:f.lastRound,date:f.date,stage:'Acquired',sourceLabel:'Existing acquisition research',url:latestNews(c).find(n=>/wix/i.test(n.headline))?.url||d?.url};
 if(d?.status==='matched'&&d.funding?.total!=null&&d.funding.total>0)return {label:amount(d.funding.total)+' raised',kind:'funded',detail:'Total funding recorded by Dealroom. This is cumulative capital raised, not the latest round amount.',date:null,retrieved:d.checkedAt?.slice(0,10),stage:stage||null,stageDate:f.date,sourceLabel:'Dealroom',url:d.url};
 if(/bootstrapped|self-funded/i.test(f.totalRaised||''))return {label:'Self-funded',kind:'bootstrap',detail:f.totalRaised,date:f.date,stage:null,sourceLabel:'Existing research; not freshly verified',url:null};
 return {label:stage||'Not recorded',kind:stage?'stage':'unknown',detail:f.lastRound||'No dated capital milestone recorded.',date:f.date,stage:stage||null,sourceLabel:'Existing research; not freshly verified',url:null};
}
