function frontierResearch(){const cards=frontierFindings.filter(x=>x.join(' ').toLowerCase().includes(state.q.toLowerCase()));document.querySelector('#count').textContent=cards.length+' findings';return `<div class="frontier-research-intro"><span class="positioning-eyebrow">THE RESEARCH BEHIND THE THESIS</span><h3>Growth is one axis. Operating leverage is the other.</h3><p>ICONIQ examines 137 software companies through Q2 2026. Pacesetters are a changing subset selected by growth within ARR bands and AI orientation. The entire sample is not a list of rapid-growth winners.</p>${frontierSource('iconiq')}</div><div class="frontier-findings">${cards.map((x,i)=>`<article><span class="positioning-eyebrow">0${i+1} / ICONIQ ${x[2]}</span><h3>${x[0]}</h3><p>${x[1]}</p><div><strong>Track in Autopilot Index</strong><p>${x[3]}</p></div></article>`).join('')}</div><div class="frontier-section-title"><h3>Three complementary investor lenses</h3><span>Selected cohorts and opinions; not population-wide forecasts.</span></div><div class="frontier-investors"><article><span>BESSEMER / BENCHMARKS</span><h3>Supernovas & Shooting Stars</h3><p>Study of 20 selected AI startups. The ten Supernovas average ~$40M ARR in year one and ~$125M in year two, with ~25% gross margin and $1.13M ARR/FTE. Shooting Stars average ~60% gross margin.</p><p>Useful question: how much durable gross profit sits behind the growth?</p>${frontierSource('bvp')}</article><article><span>SEQUOIA / THESIS</span><h3>From the $100M club to $1B</h3><p>David Cahn’s December 2025 essay anticipates a $0-to-$1B club and points to AI use inside company functions. This is a directional thesis, not a verified solo-founder dataset.</p>${frontierSource('sequoia')}</article><article><span>ACCEL / COMPANY CASE</span><h3>Distribution compounds</h3><p>The Cursor investment essay describes integrations, an expanding developer workflow and product adoption. The primary company announcement supplies the precise annualized-revenue label and team count.</p>${frontierSource('accel')}</article></div><details class="frontier-method"><summary>Companies extracted from the ICONIQ examples</summary><p><strong>Growth curves · p25:</strong> Anthropic, Legora, Sierra, ElevenLabs, OpenAI, Glean.</p><p><strong>Growth-mechanics interviews · p28:</strong> Anthropic, Braintrust, ElevenLabs, Glean, Legora, Sierra, Snowflake.</p><p><strong>Operating-role examples · p32:</strong> Anthropic, ElevenLabs, Legora, Sierra, Grotto AI.</p><p>These sets overlap. Page 4 is the broader study universe; page 49 is a portfolio list. Neither is a ranking of the fastest companies.</p></details><details class="frontier-method"><summary>How to interpret the original ICONIQ chart</summary><p>Page 25 plots approximately 4 quarters for Anthropic, 6 for Legora, 7 for Sierra, 8 for ElevenLabs and OpenAI, and 12 for Glean. These are approximate chart readings, not independently established milestone dates.</p><p>The report uses ARR or revenue, exponential interpolation and a $1M or product-launch baseline depending on availability. It assumes 24 months from founding to $1M when undisclosed. Its curves should not be reused as observed monthly revenue histories. In the report, n can mean company-quarter observations rather than unique companies.</p></details>`}
function frontierNetworks(){let ns=FRONTIER.networks.filter(n=>JSON.stringify(n).toLowerCase().includes(state.q.toLowerCase()));document.querySelector('#count').textContent=ns.length+' documented connections';return `<section class="frontier-research-intro"><span class="positioning-eyebrow">FOUNDER NETWORKS</span><h3>Where the next generation learns to build.</h3><p>Follow documented career connections and new ventures. A shared employer is a connection; future breakout success remains a hypothesis.</p></section><div class="frontier-network-list">${ns.map(n=>`<article><span>${E(n.from)}</span><b>→</b><strong>${E(n.person)}</strong><b>→</b><span class="frontier-destination">${E(n.to)}</span><div>${E(n.detail)} ${frontierSource(n.source)}</div></article>`).join('')}</div><section class="frontier-watch"><span class="positioning-eyebrow">NEXT-GENERATION WATCH / EDITORIAL HYPOTHESIS</span><h3>Watch the people leaving today’s frontier.</h3><p>Cursor · Lovable · Base44 / Wix · Legora · Sierra · ElevenLabs · Anthropic · Glean</p><p>Next records to collect: public departure → named founder → new venture → launch → tools → first commercial evidence. No future spinouts are asserted here.</p></section>`}
render=function(){if(state.tab!=='$1B Solo Founder 🚀'){beforeFrontierRender();return}document.querySelector('#results').innerHTML=state.frontierView==='Research'?frontierResearch():state.frontierView==='Founder networks'?frontierNetworks():frontierMilestones()};
function frontierDetail(id){const r=FRONTIER.records.find(r=>r.id===id);if(!r)return;const s=FRONTIER.sources[r.source];modal(r.name+' · milestone evidence',`<div class="frontier-detail-value">${E(r.display)}</div><p>${E(r.notes)}</p><dl class="frontier-detail-grid"><dt>Metric</dt><dd>${E(r.metric)} · USD as reported</dd><dt>Entity scope</dt><dd>${E(r.entity)}</dd><dt>Clock</dt><dd>${E(r.clock)} → ${E(r.duration)}</dd><dt>Milestone / observation</dt><dd>${E(r.date)}</dd><dt>Source published</dt><dd>${E(s.date||'Unknown')}</dd><dt>Team</dt><dd>${E(r.team)}</dd><dt>Evidence</dt><dd>${E(s.type)} · ${frontierSource(r.source)}</dd><dt>Research checked</dt><dd>${FRONTIER.checkedAt}</dd></dl><h3>What builders can study</h3><p>${E(r.mechanism)}. This describes the product or operating pattern; causal impact on growth has not been established.</p><h3>Open research fields</h3><p>Gross margin · net retention · compute cost · contractor and deployment team size · dated ARR per FTE · actual human oversight · verified stack. Missing values remain unknown.</p>${r.id==='cursor'?'<p><strong>Capital context:</strong> the same November 2025 announcement reports a $29.3B post-money valuation and $2.3B financing. These are distinct from annualized revenue.</p>':''}${r.id==='base44'?'<button class="frontier-method-button" data-company="base44">Open company fundamentals ＋</button>':''}`)}
listen(app,'click',e=>{let target=e.target.closest('[data-frontier],[data-frontier-method],[data-action="reset"]');if(!target)return;if(target.dataset.frontier)frontierDetail(target.dataset.frontier);else if(target.hasAttribute('data-frontier-method'))modal('The $1B Solo Founder 🚀 thesis',`<h2>More output. Fewer constraints. Evidence first.</h2><p>Our research question: can AI let smaller teams build enduring businesses at a scale that once required much larger organizations?</p><p>Track three independent dimensions: <strong>commercial scale</strong> (revenue or ARR), <strong>operating leverage</strong> (team, costs and human intervention), and <strong>company value</strong> (dated valuation or exit).</p><p>A $1B valuation can occur before $100M ARR. Reaching $100M does not guarantee reaching $1B. The current evidence does not establish a one-person billion-dollar business.</p><h3>Comparable evidence</h3><p>Preserve original currency, metric definition, entity scope, baseline and event date. Dollars here are USD; no GBP conversion is implied. ARR is recurring revenue annualized; a revenue run rate can include non-recurring activity. Neither means revenue already earned over a full year.</p><p>Attach source and observation dates to team size. Include contractors, service providers, parent-company support and compute costs when judging whether a company really operates smaller.</p><p>These records are a curated research snapshot, not an automated monitoring feed. Subsequent observations should append to the history rather than overwrite it.</p>`);else{Object.assign(state,{frontierMetric:'All',frontierScope:'All'});controls();render()}});
