function flightLogo(r){return flightLogos[r.id]?`<img class="flight-logo" src="/registry/assets/${flightLogos[r.id]}.${r.id==='microagi'?'svg':'png'}" alt="" loading="lazy">`:`<span class="frontier-monogram">${E(r.name.slice(0,2))}</span>`}
