function flightPoint(o,position){return `<button class="flight-point" style="left:${position}%" data-flight-observation="${o.companyId}|${o.source}" aria-label="${E(o.companyId)}: ${E(o.relation==='greater_than'?'>':'')}$${o.value}M ARR, announced ${E(o.announcedAt)}" title="$${o.value}M ARR · ${o.announcedAt} · open evidence"></button>`}
function flightChart(){const candidates=FRONTIER.records.filter(frontierMatches);let shown=[];let ticks=[],unit='',rows='',note='';
 if(state.flightView==='Time to $100M'){
  shown=candidates.filter(r=>r.metric==='ARR'&&r.value===100&&r.months&&FRONTIER.sources[r.source].date<=state.flightAsOf&&(state.flightClock==='All clocks'||r.clock===state.flightClock)).sort((a,b)=>a.months-b.months);
  ticks=[0,6,12,18,24];unit='MONTHS TO $100M ARR';
  rows=shown.map(r=>`<div class="flight-row">${flightName(r,'From '+r.clock)}<div class="flight-track"><span class="flight-stem" style="width:${r.months/24*100}%"></span><button class="flight-endpoint" data-frontier="${r.id}" style="left:${r.months/24*100}%" aria-label="${E(r.name)}: ${E(r.duration)} from ${E(r.clock)}"><span></span><b>${r.months===12?'~':''}${r.months} mo</b></button></div><div class="flight-right">$100M ARR<small>${E(r.date)}</small></div></div>`).join('');
  note='Shorter = faster. All clocks is an overview of differently defined journeys; choose a starting point for comparable rows. Unknown durations and run-rate claims are excluded.';
 }else if(state.flightView==='Scale'){
  shown=candidates.filter(r=>flightHistory(r.id).length).sort((a,b)=>flightHistory(b.id).at(-1).value-flightHistory(a.id).at(-1).value);
  ticks=[0,250,500,750,1000];unit='REPORTED ARR · USD MILLIONS';
  rows=shown.map(r=>{const hs=flightHistory(r.id),o=hs.at(-1);return `<div class="flight-row">${flightName(r,r.entity)}<div class="flight-track"><span class="flight-stem" style="width:${Math.min(o.value/10,100)}%"></span>${hs.slice(0,-1).map(h=>flightPoint(h,Math.min(h.value/10,100))).join('')}<button class="flight-endpoint" style="left:${Math.min(o.value/10,100)}%" data-flight-observation="${r.id}|${o.source}" aria-label="${E(r.name)}: $${o.value}M ARR. Open source"><span></span><b>${o.relation==='greater_than'?'>':''}$${o.value}M</b></button></div><div class="flight-right">${E(o.announcedAt)}<small>announcement date</small></div></div>`}).join('');
  note='Linear scale to $1B ARR. Filled dot = most recent observation in this snapshot; hollow dot = earlier report. A line shows position, not a measured revenue path. Run rates and valuations are excluded.';
 }else{
  shown=candidates.filter(r=>flightHistory(r.id).length>=2).map(r=>{const hs=flightHistory(r.id),a=hs.at(-2),b=hs.at(-1),months=(Date.parse(b.announcedAt)-Date.parse(a.announcedAt))/86400000/30.4375;return {r,a,b,months,pace:(b.value-a.value)/months}}).filter(x=>Number.isFinite(x.pace)&&x.months>0).sort((a,b)=>b.pace-a.pace);
  ticks=[0,10,20,30,40];unit='CHANGE IN REPORTED ARR / MONTH · $M';
  rows=shown.map(x=>`<div class="flight-row">${flightName(x.r,`${x.a.announcedAt} → ${x.b.announcedAt}`)}<div class="flight-track"><span class="flight-stem" style="width:${Math.min(x.pace/40*100,100)}%"></span><button class="flight-endpoint" style="left:${Math.min(x.pace/40*100,100)}%" data-flight-observation="${x.r.id}|${x.b.source}" aria-label="${E(x.r.name)}: approximate reported ARR change $${x.pace.toFixed(1)}M per month"><span></span><b>+$${x.pace.toFixed(1)}M/mo</b></button></div><div class="flight-right">$${x.a.value}M → $${x.b.value}M<small>${x.months.toFixed(1)} months between reports</small></div></div>`).join('');
  note='Historical reporting pace, not current growth: change in disclosed ARR ÷ months between announcement dates (30.4375 days/month). Different observation windows; crossing dates may precede announcements. Two compatible observations required. No projection to $1B.';
 }
 return `<section class="flight-board" aria-label="Company growth comparison"><div class="flight-heading"><div><span class="positioning-eyebrow">THE RACE TO SCALE</span><h3>Small teams. Bigger trajectories.</h3><p>The solo-founder thesis, studied through companies of every team size.</p></div><div class="flight-switches">${selectGroup('flightView',['Time to $100M','Scale','Momentum'])}</div></div><div class="flight-options">${state.flightView==='Time to $100M'?`<span>Starting point</span>${selectGroup('flightClock',['All clocks','$1M ARR','Founding','Platform launch'])}`:'<span>ARR only · latest available in this snapshot</span>'}<label>Evidence available by <select id="flight-asof"><option ${state.flightAsOf==='2025-12-31'?'selected':''}>2025-12-31</option><option ${state.flightAsOf==='2026-06-30'?'selected':''}>2026-06-30</option><option ${state.flightAsOf==='2026-10-12'?'selected':''}>2026-10-12</option></select></label></div><div class="flight-scroll"><div class="flight-grid"><div class="flight-axis"><span>${shown.length} ${state.flightView==='Momentum'?'reporting intervals':'companies'}</span><div>${ticks.map((n,i)=>`<span style="left:${i*25}%">${n===1000?'$1B':n===0?'0':state.flightView==='Time to $100M'?n+' mo':'$'+n+'M'}</span>`).join('')}</div><span>${unit}</span></div>${rows||'<p class="flight-empty">No comparable observations for these filters and date. Choose another view or reset.</p>'}</div></div><p class="flight-note">${note} Select a dot for its evidence.</p><details class="flight-update"><summary>How this tracker moves as companies scale</summary><p>Every new sourced disclosure adds a dated observation. Scale moves to the new value; the older dot stays visible. Momentum recalculates from the latest compatible pair. Keep the metric, entity, currency and reporting window attached. A new funding valuation does not move ARR.</p><p>For a fair live leaderboard: compare the same milestone and starting clock, show announcement age, and rank growth over matched windows when data exists. Team size and ARR per employee need observations from the same period. This preview stores historical observations; automatic collection and review are not connected yet.</p></details></section>`
}
