const capitalReviewed = {
  polsia: {name:'True Ventures · founder announcement',url:'https://www.linkedin.com/posts/true-ventures_the-future-of-company-building-is-going-to-activity-7463640028108451840-qbrK'},
  'retell-ai': {name:'Retell AI · seed announcement',url:'https://www.retellai.com/blog/seed-announcement'}
};
const capitalAngels = new Set(['Paul Graham','Andy Dunn','Leah Solivan','Andrew Yeung','Aaron Levie','Jeff Dean','Rajat Suri','Siqi Chen','Alex Levin','Michael Seibel','Tyler Bosmeny']);
const capitalAliases = {'a16z':'Andreessen Horowitz','Sequoia':'Sequoia Capital','Carya Ventures':'Carya Venture'};
const capitalExtraAngels = ['Rajat Suri','Aaron Levie','Siqi Chen','Alex Levin','Michael Seibel','Tyler Bosmeny'];
const capitalNotes = [];
const capitalEdges = companies.flatMap(c => {
  const raw = [...(c.funding?.investors || [])];
  if(c.slug==='retell-ai') raw.push(...capitalExtraAngels);
  if(c.slug==='polsia') capitalNotes.push({slug:c.slug,text:'The announcement also mentions angels without naming them. Individual angels remain unassigned.'});
  return raw.flatMap(label => {
    if(/\d+.*(?:angels|customers)/i.test(label)) {capitalNotes.push({slug:c.slug,text:label+' — individual names not recorded.'});return [];}
    const names = label==='Aaron Levie & Jeff Dean (angels)' ? ['Aaron Levie','Jeff Dean'] : [label.replace(/\s*\(.*\)\s*$/,'').trim()];
    return names.map(name => {
      name=capitalAliases[name]||name;
      const kind=/parent/i.test(label)?'Parent':/grant/i.test(label)?'Grant':capitalAngels.has(name)?'Angel':'Fund / institution';
      const source=capitalReviewed[c.slug]||c.metrics?.sources?.raised||null;
      return {name,kind,slug:c.slug,label,source,checkedAt:capitalReviewed[c.slug]?'2026-10-12':null,scope:c.slug==='nanocorp'?'Parent Phospho':c.slug==='chainopera-ai'?'Company / sister-company scope in source':'Company',role:/\(lead\)/i.test(label)?'Lead reported':'Backer recorded'};
    });
  });
});
